{"sql": "WITH RECURSIVE sort_word AS (
    SELECT 'cruth' as word, 1 as pos
),
chars AS (
    SELECT SUBSTR(word, pos, 1) as letter, pos, word
    FROM sort_word, UNNEST(SEQUENCE(1, LENGTH(word))) as pos
),
sorted AS (
    SELECT letter FROM chars ORDER BY letter
)
SELECT STRING_AGG(letter, '') FROM sorted", "preview_rows": 5}

